.thread-link {
    background: none;
    border: none;
    color: #228be6;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Message action buttons ── */
.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.action-btn {
    background: none;
    border: none;
    font-size: 0.78rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #495057;
    white-space: nowrap;
}

.action-btn:hover {
    background: #e9ecef;
}

/* ── Emoji picker ── */
.emoji-picker {
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 6px;
    margin-top: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    width: fit-content;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.3rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-btn:hover {
    background: #e9ecef;
}

/* ── Message input ── */
.message-input-area {
    padding: 12px 24px;
    border-top: 1px solid #dee2e6;
    background: #fff;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

.message-input {
    flex: 1;
    resize: none;
    border: 1px solid #ced4da;
    border-radius: 8px;
    padding: 10px 14px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input:focus {
    border-color: #228be6;
    box-shadow: 0 0 0 2px rgba(34,139,230,0.15);
}

.send-btn {
    background: #228be6;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #1c7ed6;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ── Thread panel ── */
.chat-thread {
    width: 25%;
    min-width: 260px;
    display: flex;
    flex-direction: column;
    background: #fff;
    border-left: 1px solid #dee2e6;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 20px;
    border-bottom: 1px solid #dee2e6;
}

.thread-header h5 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-thread-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: #868e96;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #e9ecef;
    color: #212529;
}

.thread-root-quote {
    padding: 12px 20px;
    background: #f1f3f5;
    border-bottom: 1px solid #dee2e6;
    border-left: 3px solid #228be6;
    margin: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 6px 10px;
}

/* ── Thread panel input reuses .message-input-area styles ── */
.chat-thread .message-input-area {
    padding: 12px 16px;
}
"}

