    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #8d99ae;
}

.channel-list {
    list-style: none;
    padding: 8px 0;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 10px 20px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: rgba(255,255,255,0.06);
}

.channel-item.active {
    background: rgba(255,255,255,0.12);
    border-left: 3px solid #ef233c;
    padding-left: 17px;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-desc {
    font-size: 0.75rem;
    color: #8d99ae;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    background: #ef233c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    min-width: 20px;
    text-align: center;
}

/* ── Main area ── */
.chat-main {
    width: 55%;
    display: flex;
    flex-direction: column;
    background: #f8f9fa;
    transition: width 0.2s ease;
}

.chat-main.expanded {
    width: 80%;
}

.main-header {
    padding: 14px 24px;
    border-bottom: 1px solid #dee2e6;
    background: #fff;
}

.main-header h5 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

.header-desc {
    font-size: 0.8rem;
    color: #6c757d;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 24px;
}

.loading-indicator {
    text-align: center;
    padding: 10px;
    color: #6c757d;
    font-size: 0.85rem;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
    font-size: 1.1rem;
}

/* ── Messages ── */
.message-row {
    padding: 8px 12px;
    border-radius: 6px;
    margin-bottom: 4px;
    position: relative;
    transition: background 0.1s;
}

.message-row:hover {
    background: #e9ecef;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.msg-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #212529;
}

.msg-time {
    font-size: 0.75rem;
    color: #868e96;
}

.msg-content {
    font-size: 0.9rem;
    color: #343a40;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

/* ── Reactions ── */
.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    background: #e9ecef;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
    line-height: 1.4;
}

.reaction-badge:hover {
    background: #d0d4da;
}

/* ── Thread link ── */
.thread-link {
    background: none;
    border: none;
    color: #228be6;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Message action buttons ── */
.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.action-btn {
    background: none;
    border: none;
    font-size: 0.78rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #495057;
    white-space: nowrap;
}

.action-btn:hover {
    background: #e9ecef;
}

/* ── Emoji picker ── */
.emoji-picker {
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 6px;
    margin-top: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    width: fit-content;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.3rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-btn:hover {
    background: #e9ecef;
}

/* ── Message input ── */
.message-input-area {
    padding: 12px 24px;
    border-top: 1px solid #dee2e6;
    background: #fff;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

.message-input {
    flex: 1;
    resize: none;
    border: 1px solid #ced4da;
    border-radius: 8px;
    padding: 10px 14px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input:focus {
    border-color: #228be6;
    box-shadow: 0 0 0 2px rgba(34,139,230,0.15);
}

.send-btn {
    background: #228be6;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #1c7ed6;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ── Thread panel ── */
.chat-thread {
    width: 25%;
    min-width: 260px;
    display: flex;
    flex-direction: column;
    background: #fff;
    border-left: 1px solid #dee2e6;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 20px;
    border-bottom: 1px solid #dee2e6;
}

.thread-header h5 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-thread-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: #868e96;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #e9ecef;
    color: #212529;
}

.thread-root-quote {
    padding: 12px 20px;
    background: #f1f3f5;
    border-bottom: 1px solid #dee2e6;
    border-left: 3px solid #228be6;
    margin: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 6px 10px;
}

/* ── Thread panel input reuses .message-input-area styles ── */
.chat-thread .message-input-area {
    padding: 12px 16px;
}

