private async Task OnMainScroll()
{
    // This fires on every scroll event; actual scroll-to-top detection
    // would require JS interop. We use a simplified approach here:
    // the handler is wired up so that a JS interop call can trigger loading.
    // For now, we expose the method and rely on the loading button fallback.
}

// ── Helpers ──

arguments.new_str:
// ── JS Interop for scroll ──

private IJSObjectReference? _jsModule;
private DotNetObjectReference<Chat>? _dotNetRef;

protected override async Task OnAfterRenderAsync(bool firstRender)
{
    if (firstRender)
    {
        _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
            "./Components/Pages/Chat.razor.js");
        _dotNetRef = DotNetObjectReference.Create(this);
    }

    // Register scroll handler whenever the message list element is (re-)rendered
    if (_jsModule is not null && _dotNetRef is not null && _messages is not null)
    {
        await _jsModule.InvokeVoidAsync("registerScrollHandler", _messageListRef, _dotNetRef);
    }
}

[JSInvokable]
public async Task OnScrolledToTop()
{
    await LoadOlderMessagesAsync();
    await InvokeAsync(StateHasChanged);
}

public async ValueTask DisposeAsync()
{
    _dotNetRef?.Dispose();
    if (_jsModule is not null)
    {
        await _jsModule.DisposeAsync();
    }
}

// ── Helpers ──

